// ===== Decidir estado (Memoria Buffer Pool) =====
const P = $node['Set - Params'].json || {};
const th = Number(P.threshold ?? P.threshold_mem ?? 90);  // prioriza "threshold"
const row = $node['MSSQL – BufferPool']?.json || {};
const pct = Number(row.PorcentajeUso ?? row.porcentajeUso ?? row.porcentaje ?? 0);
const total = Number(row.MemoriaTotal_MB ?? 0);
const used = Number(row.MemoriaUtilizada_MB ?? 0);

const g = $getWorkflowStaticData('global');
const last = g.last_state || 'OK';
const state = (pct >= th) ? 'ALARM' : 'OK';
let transition = 'NONE';
const nowIso = new Date().toISOString();
if (state !== last) {
  transition = (state === 'ALARM') ? 'RAISE' : 'RECOVERY';
  g.last_state = state; g.last_change = nowIso;
}
g.last_seen = nowIso;

const tz = Number(P.tz_offset_hours ?? 0);
const local = new Date(Date.now() + tz*3600*1000).toISOString().replace('T',' ').substring(0,19);

return [{
  json: {
    state, transition, threshold: th,
    instance_name: P.instance_name,
    mem_total_mb: total, mem_used_mb: used, mem_used_pct: pct,
    queryTimeUTC: nowIso, queryTimeLocal: local
  }
}];

