/* ===== Registry memoria en OpsObservability ===== */
SET NOCOUNT ON;
SET ARITHABORT ON;
USE OpsObservability;

DECLARE @now_utc DATETIME = GETUTCDATE();
SET @now_utc = DATEADD(SECOND, DATEDIFF(SECOND,'20000101',@now_utc), '20000101');

DECLARE @inst_name NVARCHAR(200);
SET @inst_name = N'{{$node["Set - Params"].json["instance_name"]}}';

DECLARE @env NVARCHAR(50);
SET @env = N'{{$node["Set - Params"].json["environment"]}}';

DECLARE @reg NVARCHAR(50);
SET @reg = N'{{$node["Set - Params"].json["region"]}}';

DECLARE @id INT = (SELECT instance_id FROM dbo.monitoring_instance WHERE instance_name=@inst_name);
IF @id IS NULL
BEGIN
  INSERT INTO dbo.monitoring_instance(instance_name, environment, region)
  VALUES(@inst_name, @env, @reg);
  SET @id = SCOPE_IDENTITY();
END;

/* === Params desde Function – Decidir estado (compatible 2008R2) === */
DECLARE @used_pct FLOAT, @total_mb FLOAT, @used_mb FLOAT, @prefix NVARCHAR(100);

BEGIN TRY
  SET @used_pct = CAST('{{$node["Function – Decidir estado"].json["mem_used_pct"]}}' AS FLOAT);
END TRY BEGIN CATCH
  SET @used_pct = NULL;
END CATCH;

BEGIN TRY
  SET @total_mb = CAST('{{$node["Function – Decidir estado"].json["mem_total_mb"]}}' AS FLOAT);
END TRY BEGIN CATCH
  SET @total_mb = NULL;
END CATCH;

BEGIN TRY
  SET @used_mb = CAST('{{$node["Function – Decidir estado"].json["mem_used_mb"]}}' AS FLOAT);
END TRY BEGIN CATCH
  SET @used_mb = NULL;
END CATCH;

SET @prefix = N'{{$node["Set - Params"].json["registry_metric_prefix"]}}';

/* Limpiar posibles duplicados del mismo ts/instancia/métrica */
DELETE FROM dbo.monitoring_metric_timeseries
WHERE instance_id=@id AND ts_utc=@now_utc AND metric_name IN
(
  @prefix + ':used_pct',
  @prefix + ':total_mb',
  @prefix + ':used_mb'
);

/* Insertar mediciones (una fila por métrica) */
INSERT INTO dbo.monitoring_metric_timeseries
(ts_utc, instance_id, metric_name, metric_value, dim_json, run_id)
VALUES
(@now_utc, @id, @prefix+':used_pct',  ISNULL(@used_pct,0), NULL, NEWID()),
(@now_utc, @id, @prefix+':total_mb',  ISNULL(@total_mb,0), NULL, NEWID()),
(@now_utc, @id, @prefix+':used_mb',   ISNULL(@used_mb,0),  NULL, NEWID());

/* ===== Reportería básica (tops mem) ===== */
SET NOCOUNT ON;
USE OpsObservability;

DECLARE @now_utc DATETIME = GETUTCDATE();
SET @now_utc = DATEADD(SECOND, DATEDIFF(SECOND,'20000101',@now_utc), '20000101');

DECLARE @inst_name NVARCHAR(200);
SET @inst_name = N'{{$node["Set - Params"].json["instance_name"]}}';

DECLARE @id INT = (SELECT instance_id FROM dbo.monitoring_instance WHERE instance_name=@inst_name);
IF @id IS NULL
BEGIN
  INSERT INTO dbo.monitoring_instance(instance_name) VALUES(@inst_name);
  SET @id = SCOPE_IDENTITY();
END;

DECLARE @used_pct FLOAT, @total_mb FLOAT, @used_mb FLOAT;
DECLARE @rid UNIQUEIDENTIFIER = NEWID();

/* === Tomar valores desde "Function – Decidir estado" (compatibles 2008 R2) === */
BEGIN TRY
  SET @used_pct = CAST('{{$node["Function – Decidir estado"].json["mem_used_pct"]}}' AS FLOAT);
END TRY BEGIN CATCH
  SET @used_pct = NULL;
END CATCH;

BEGIN TRY
  SET @total_mb = CAST('{{$node["Function – Decidir estado"].json["mem_total_mb"]}}' AS FLOAT);
END TRY BEGIN CATCH
  SET @total_mb = NULL;
END CATCH;

BEGIN TRY
  SET @used_mb = CAST('{{$node["Function – Decidir estado"].json["mem_used_mb"]}}' AS FLOAT);
END TRY BEGIN CATCH
  SET @used_mb = NULL;
END CATCH;

/* Limpiar claves del mismo ts/instancia para evitar PK duplicada */
DELETE FROM dbo.monitoring_top_entities
WHERE instance_id=@id
  AND ts_utc=@now_utc
  AND scope_type='mem'
  AND scope_key IN ('buffer_pool.used_pct','buffer_pool.used_mb','buffer_pool.total_mb');

/* Insertar “tops” básicos de memoria del buffer pool */
INSERT INTO dbo.monitoring_top_entities
(ts_utc, instance_id, scope_type, scope_key,     metric_name,     metric_value,     rank_n, run_id)
VALUES
(@now_utc, @id, 'mem', 'buffer_pool.used_pct',  'mem_used_pct',  ISNULL(@used_pct,0),  0,    @rid),
(@now_utc, @id, 'mem', 'buffer_pool.used_mb',   'mem_used_mb',   ISNULL(@used_mb,0),   0,    @rid),
(@now_utc, @id, 'mem', 'buffer_pool.total_mb',  'mem_total_mb',  ISNULL(@total_mb,0),  0,    @rid);

/* Confirmación para n8n */
SELECT 'tops_mem inserted' AS message, @now_utc AS ts_utc, @id AS instance_id;

/* ===== Diagnostics Memoria – inserta tops y devuelve resúmenes para Teams ===== */
SET NOCOUNT ON;

DECLARE @N INT;
BEGIN TRY
    SET @N = CAST('{{$node["Set - Params"].json["tops_n"]}}' AS INT);
END TRY
BEGIN CATCH
    SET @N = 5;
END CATCH;
IF @N IS NULL SET @N = 5;

DECLARE @inst_name NVARCHAR(200);
SET @inst_name = N'{{$node["Set - Params"].json["instance_name"]}}';

/* Ensure instance exists and get id */
USE OpsObservability;
DECLARE @id INT = (SELECT instance_id FROM dbo.monitoring_instance WHERE instance_name=@inst_name);
IF @id IS NULL BEGIN INSERT INTO dbo.monitoring_instance(instance_name) VALUES(@inst_name); SET @id = SCOPE_IDENTITY(); END;

DECLARE @now_utc DATETIME = GETUTCDATE();
SET @now_utc = DATEADD(SECOND, DATEDIFF(SECOND,'20000101',@now_utc), '20000101');
DECLARE @rid UNIQUEIDENTIFIER = NEWID();

/* Clean old rows for same timestamp */
DELETE FROM dbo.monitoring_top_entities
WHERE instance_id=@id AND ts_utc=@now_utc AND scope_type IN ('mem_diag');

/********* Collect from target instance *********/
USE master;

/* 1) Top DB cache (buffer descriptors) */
IF ({{$node["Set - Params"].json["collect_db_cache"] ? 1 : 0}})=1
BEGIN
  ;WITH cte AS (
    SELECT
      DB_NAME(database_id) AS db,
      CONVERT(float, COUNT(*)) * 8.0 / 1024.0 AS cached_mb
    FROM sys.dm_os_buffer_descriptors WITH (NOLOCK)
    WHERE database_id <> 32767
    GROUP BY database_id
  )
  INSERT INTO OpsObservability.dbo.monitoring_top_entities
    (ts_utc,instance_id,scope_type,scope_key,metric_name,metric_value,rank_n,run_id)
  SELECT TOP (@N)
    @now_utc,@id,'mem_diag','db_cache:'+db,'cache_mb',cached_mb,
    ROW_NUMBER() OVER (ORDER BY cached_mb DESC), @rid
  FROM cte
  ORDER BY cached_mb DESC;
END;

/* 2) Top sesiones agrupadas por login|programa */
IF ({{$node["Set - Params"].json["collect_sessions"] ? 1 : 0}})=1
BEGIN
  ;WITH cte AS (
    SELECT
      ISNULL(s.login_name,'?')   AS login_name,
      ISNULL(s.program_name,'?') AS program_name,
      SUM(CONVERT(float, s.memory_usage) * 8.0 / 1024.0) AS mem_mb
    FROM sys.dm_exec_sessions s WITH (NOLOCK)
    WHERE s.is_user_process = 1
    GROUP BY s.login_name, s.program_name
  )
  INSERT INTO OpsObservability.dbo.monitoring_top_entities
    (ts_utc,instance_id,scope_type,scope_key,metric_name,metric_value,rank_n,run_id)
  SELECT TOP (@N)
    @now_utc,@id,'mem_diag',
    'session:' + login_name + '|' + program_name,
    'session_mem_mb', mem_mb,
    ROW_NUMBER() OVER (ORDER BY mem_mb DESC), @rid
  FROM cte
  ORDER BY mem_mb DESC;
END;

/* 3) Top memory clerks */
IF ({{$node["Set - Params"].json["collect_clerks"] ? 1 : 0}})=1
BEGIN
  ;WITH cte AS (
    SELECT
      [type],
      CONVERT(float,(ISNULL(single_pages_kb,0)+ISNULL(multi_pages_kb,0))) / 1024.0 AS clerk_mb
    FROM sys.dm_os_memory_clerks WITH (NOLOCK)
  )
  INSERT INTO OpsObservability.dbo.monitoring_top_entities
    (ts_utc,instance_id,scope_type,scope_key,metric_name,metric_value,rank_n,run_id)
  SELECT TOP (@N)
    @now_utc,@id,'mem_diag','clerk:'+[type],'clerk_mb',clerk_mb,
    ROW_NUMBER() OVER (ORDER BY clerk_mb DESC), @rid
  FROM cte
  ORDER BY clerk_mb DESC;
END;

/* 4) Memory grants (active) — agregado por session_id para evitar duplicados */
IF ({{$node["Set - Params"].json["collect_grants"] ? 1 : 0}})=1
BEGIN
  ;WITH cte AS (
    SELECT
      session_id,
      SUM(CAST(used_memory_kb AS float)) / 1024.0 AS used_mb
    FROM sys.dm_exec_query_memory_grants WITH (NOLOCK)
    GROUP BY session_id
  )
  INSERT INTO OpsObservability.dbo.monitoring_top_entities
    (ts_utc,instance_id,scope_type,scope_key,metric_name,metric_value,rank_n,run_id)
  SELECT TOP (@N)
    @now_utc, @id, 'mem_diag',
    'grant:' + CAST(session_id AS nvarchar(10)),
    'grant_used_mb', ISNULL(used_mb,0.0),
    ROW_NUMBER() OVER (ORDER BY used_mb DESC), @rid
  FROM cte
  ORDER BY used_mb DESC;
END;

/* Return compact summaries for Teams card */
;WITH S AS (
  SELECT scope_type, scope_key, metric_name, metric_value, rank_n
  FROM OpsObservability.dbo.monitoring_top_entities WITH (NOLOCK)
  WHERE instance_id=@id AND ts_utc=@now_utc AND scope_type='mem_diag'
)
SELECT
  (SELECT TOP (@N) REPLACE(scope_key,'db_cache:','') + ': ' +
          CONVERT(nvarchar(30), CAST(metric_value as decimal(18,2))) + ' MB'
   FROM S WHERE scope_key LIKE 'db_cache:%' ORDER BY rank_n
   FOR XML PATH(''), TYPE).value('.','nvarchar(max)') AS top_db_cache,
  (SELECT TOP (@N) REPLACE(scope_key,'session:','') + ': ' +
          CONVERT(nvarchar(30), CAST(metric_value as decimal(18,2))) + ' MB'
   FROM S WHERE scope_key LIKE 'session:%' ORDER BY rank_n
   FOR XML PATH(''), TYPE).value('.','nvarchar(max)') AS top_sessions,
  (SELECT TOP (@N) REPLACE(scope_key,'clerk:','') + ': ' +
          CONVERT(nvarchar(30), CAST(metric_value as decimal(18,2))) + ' MB'
   FROM S WHERE scope_key LIKE 'clerk:%' ORDER BY rank_n
   FOR XML PATH(''), TYPE).value('.','nvarchar(max)') AS top_clerks,
  (SELECT TOP (@N) REPLACE(scope_key,'grant:','') + ': ' +
          CONVERT(nvarchar(30), CAST(metric_value as decimal(18,2))) + ' MB'
   FROM S WHERE scope_key LIKE 'grant:%' ORDER BY rank_n
   FOR XML PATH(''), TYPE).value('.','nvarchar(max)') AS top_grants;

