function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// ===== Build Teams payload (ALERTA – Memoria) con glosario =====
const P = $node['Set - Params']?.json || {};
const S = $node['Function – Decidir estado']?.json || {};
const D = $node['MSSQL – Mem diag & tops']?.json || {};

const num = v => (v == null ? null : Number(v));
const fmt2 = v => (Number.isFinite(num(v)) ? num(v).toFixed(2) : String(v ?? 'N/D'));
const pct  = v => (Number.isFinite(num(v)) ? `${num(v).toFixed(2)}%` : 'N/D%');

const toLocal = iso => {
  const offMs = Number(P.tz_offset_hours || 0) * 3600 * 1000;
  const d = new Date(new Date(iso || Date.now()).getTime() + offMs);
  return d.toISOString().replace('T',' ').substring(0,19);
};

// Título & subtítulo
const inst   = S.instance_name || P.instance_name || 'N/D';
const used   = pct(S.mem_used_pct);
const thr    = S.threshold ?? P.threshold ?? 'N/D';
const title  = `🔴 ALERTA  ${P.product_name || 'SQL Server'} • ${inst} • ${used} usada (umbral ${thr}%)`;
const subtitle = `ALERTA – Memoria alta (Buffer Pool) • Top ${P.tops_n ?? 5}`;

// Causas (ordenadas)
const causes = [];
if (D.top_db_cache) causes.push(`🧱 **DB cache:** ${D.top_db_cache}`);
if (D.top_sessions) causes.push(`🧑‍💻 **Sesiones:** ${D.top_sessions}`);
if (D.top_clerks)   causes.push(`📦 **Clerks:** ${D.top_clerks}`);
if (D.top_grants)   causes.push(`🧮 **Grants activos:** ${D.top_grants}`);

// Glosario (solo conceptos presentes)
const glossary = [];
if (D.top_db_cache) {
  glossary.push(`**DB cache:** páginas de datos que permanecen en memoria (buffer pool) por base. Valores altos aquí indican qué bases están ocupando más RAM.`);
}
if (D.top_sessions) {
  glossary.push(`**Sesiones:** usuarios/procesos con mayor consumo de memoria en el motor (p. ej., estructuras de ejecución, tempdb). Útil para detectar sesiones huérfanas o herramientas que consumen RAM.`);
}
if (D.top_clerks) {
  glossary.push(`**Clerks:** categorías internas que administran memoria (p. ej., CACHESTORE_SQLCP para planes ad-hoc, MEMORYCLERK_SQLQUERYEXECUTION, etc.). Ayudan a entender en qué subsistema se concentra el consumo.`);
}
if (D.top_grants) {
  glossary.push(`**Grants activos:** memoria reservada por consultas para operaciones como ordenamientos o hashes. Grants altos/persistentes suelen indicar consultas pesadas o falta de estadísticas/índices.`);
}

// Sugerencias
const tips = [
  'Revisar sesiones con mayor *memory_usage* y finalizar huérfanas.',
  'Verificar *memory_grants* elevados/pedientes.',
  'Revisar planes/estadísticas para reducir RAM requerida.',
  'Validar *max server memory* vs carga.',
  'Revisar uso de *tempdb* por sesiones.'
];

// Card (MessageCard para Teams)
const sections = [
  { text: `**${subtitle}**` },
  {
    facts: [
      { name: 'Instancia',      value: inst },
      { name: 'Hora (local)',   value: toLocal(S.queryTimeUTC) },
      { name: 'Memoria total (MB)', value: String(S.mem_total_mb ?? 'N/D') },
      { name: 'Memoria utilizada (MB)', value: String(S.mem_used_mb ?? 'N/D') },
      { name: 'Uso de memoria', value: used },
      { name: 'Umbral',         value: `${thr}%` }
    ],
    markdown: true
  },
  ...(causes.length ? [{ title: 'Posibles causas', text: causes.join('\n\n'), markdown: true }] : []),
  { title: 'Sugerencias', text: '• ' + tips.join(' • '), markdown: true },
  ...(glossary.length ? [{ title: '¿Qué significa esto?', text: glossary.map(x => `• ${x}`).join('\n'), markdown: true }] : [])
];

const card = {
  '@type': 'MessageCard',
  '@context': 'http://schema.org/extensions',
  'summary': `${P.title_prefix || 'ALERTA'} – Memoria`,
  'themeColor': 'C4314B',
  'title': title,
  'sections': sections
};

// Mantenemos este formato para que el HTTP use {{$json.card}}
