/********* Collect from target instance *********/
USE master;

/* 1) Top DB cache (buffer descriptors) */
IF ({{$node["Set - Params"].json["collect_db_cache"] ? 1 : 0}})=1
BEGIN
  ;WITH cte AS (
    SELECT
      DB_NAME(database_id) AS db,
      CONVERT(float, COUNT(*)) * 8.0 / 1024.0 AS cached_mb
    FROM sys.dm_os_buffer_descriptors WITH (NOLOCK)
    WHERE database_id <> 32767
    GROUP BY database_id
  )
  INSERT INTO OpsObservability.dbo.monitoring_top_entities
    (ts_utc,instance_id,scope_type,scope_key,metric_name,metric_value,rank_n,run_id)
  SELECT TOP (@N)
    @now_utc,@id,'mem_diag','db_cache:'+db,'cache_mb',cached_mb,
    ROW_NUMBER() OVER (ORDER BY cached_mb DESC), @rid
  FROM cte
  ORDER BY cached_mb DESC;
END;

/* 2) Top sesiones agrupadas por login|programa */
IF ({{$node["Set - Params"].json["collect_sessions"] ? 1 : 0}})=1
BEGIN
  ;WITH cte AS (
    SELECT
      ISNULL(s.login_name,'?')   AS login_name,
      ISNULL(s.program_name,'?') AS program_name,
      SUM(CONVERT(float, s.memory_usage) * 8.0 / 1024.0) AS mem_mb
    FROM sys.dm_exec_sessions s WITH (NOLOCK)
    WHERE s.is_user_process = 1
    GROUP BY s.login_name, s.program_name
  )
  INSERT INTO OpsObservability.dbo.monitoring_top_entities
    (ts_utc,instance_id,scope_type,scope_key,metric_name,metric_value,rank_n,run_id)
  SELECT TOP (@N)
    @now_utc,@id,'mem_diag',
    'session:' + login_name + '|' + program_name,
    'session_mem_mb', mem_mb,
    ROW_NUMBER() OVER (ORDER BY mem_mb DESC), @rid
  FROM cte
  ORDER BY mem_mb DESC;
END;

/* 3) Top memory clerks */
IF ({{$node["Set - Params"].json["collect_clerks"] ? 1 : 0}})=1
BEGIN
  ;WITH cte AS (
    SELECT
      [type],
      CONVERT(float,(ISNULL(single_pages_kb,0)+ISNULL(multi_pages_kb,0))) / 1024.0 AS clerk_mb
    FROM sys.dm_os_memory_clerks WITH (NOLOCK)
  )
  INSERT INTO OpsObservability.dbo.monitoring_top_entities
    (ts_utc,instance_id,scope_type,scope_key,metric_name,metric_value,rank_n,run_id)
  SELECT TOP (@N)
    @now_utc,@id,'mem_diag','clerk:'+[type],'clerk_mb',clerk_mb,
    ROW_NUMBER() OVER (ORDER BY clerk_mb DESC), @rid
  FROM cte
  ORDER BY clerk_mb DESC;
END;

/* 4) Memory grants (active) — agregado por session_id para evitar duplicados */
IF ({{$node["Set - Params"].json["collect_grants"] ? 1 : 0}})=1
BEGIN
  ;WITH cte AS (
    SELECT
      session_id,
      SUM(CAST(used_memory_kb AS float)) / 1024.0 AS used_mb
    FROM sys.dm_exec_query_memory_grants WITH (NOLOCK)
    GROUP BY session_id
  )
  INSERT INTO OpsObservability.dbo.monitoring_top_entities
    (ts_utc,instance_id,scope_type,scope_key,metric_name,metric_value,rank_n,run_id)
  SELECT TOP (@N)
    @now_utc, @id, 'mem_diag',
    'grant:' + CAST(session_id AS nvarchar(10)),
    'grant_used_mb', ISNULL(used_mb,0.0),
    ROW_NUMBER() OVER (ORDER BY used_mb DESC), @rid
  FROM cte
  ORDER BY used_mb DESC;
END;

/* Return compact summaries for Teams card */
;WITH S AS (
  SELECT scope_type, scope_key, metric_name, metric_value, rank_n
  FROM OpsObservability.dbo.monitoring_top_entities WITH (NOLOCK)
  WHERE instance_id=@id AND ts_utc=@now_utc AND scope_type='mem_diag'
)
SELECT
  (SELECT TOP (@N) REPLACE(scope_key,'db_cache:','') + ': ' +
          CONVERT(nvarchar(30), CAST(metric_value as decimal(18,2))) + ' MB'
   FROM S WHERE scope_key LIKE 'db_cache:%' ORDER BY rank_n
   FOR XML PATH(''), TYPE).value('.','nvarchar(max)') AS top_db_cache,
  (SELECT TOP (@N) REPLACE(scope_key,'session:','') + ': ' +
          CONVERT(nvarchar(30), CAST(metric_value as decimal(18,2))) + ' MB'
   FROM S WHERE scope_key LIKE 'session:%' ORDER BY rank_n
   FOR XML PATH(''), TYPE).value('.','nvarchar(max)') AS top_sessions,
  (SELECT TOP (@N) REPLACE(scope_key,'clerk:','') + ': ' +
          CONVERT(nvarchar(30), CAST(metric_value as decimal(18,2))) + ' MB'
   FROM S WHERE scope_key LIKE 'clerk:%' ORDER BY rank_n
   FOR XML PATH(''), TYPE).value('.','nvarchar(max)') AS top_clerks,
  (SELECT TOP (@N) REPLACE(scope_key,'grant:','') + ': ' +
          CONVERT(nvarchar(30), CAST(metric_value as decimal(18,2))) + ' MB'
   FROM S WHERE scope_key LIKE 'grant:%' ORDER BY rank_n
   FOR XML PATH(''), TYPE).value('.','nvarchar(max)') AS top_grants;

